/**
 * ANUVAAD KI KITAAB.
 *
 * Chaabi khud Hinglish wala shabd hai — jo app me pehle se likha tha. Isliye:
 *
 *   • Jis shabd ka anuvaad yahan nahi hai, wo Hinglish me hi dikhta hai.
 *     App tooti nahi, aadha-adhoora bhi padhne layak rehta hai.
 *   • Naya page banane wale ko koi key-list yaad nahi rakhni. `t('Naya bill')`
 *     likho, bas. Baad me `npm run check` bata dega ki kya kya bacha hai.
 *
 * Bhasha ke faisle jo jaan-boojh kar liye gaye hain:
 *
 *   • Hindi me bhi wahi shabd rakhe hain jo dukaan me bole jate hain —
 *     "बिल", "स्टॉक", "ऑर्डर", "पेमेंट"। Inka "shuddh" anuvaad (बीजक,
 *     भांडार) koi dukaandaar nahi bolta; wo padh kar ruk jayega.
 *   • Sarkari shabd — GST, GSTIN, HSN, CGST, SGST, IGST, UPI, CSV — jaise ke
 *     waise. Ye kagaz pe bhi English me hi chhapte hain.
 *   • Naam, misaal ka data (Ramesh Auto Parts, BRG-6203) aur brand yahan hain
 *     hi nahi — unka anuvaad hota hi nahi.
 */
