  '2. Apni file upload karein': { hi: '2. अपनी फाइल अपलोड करें', en: '2. Upload your file' },
  '3. Check karein, phir import': { hi: '3. जाँच लें, फिर इम्पोर्ट', en: '3. Review, then import' },
  '30 din': { hi: '30 दिन', en: '30 days' },
  Aadha: { hi: 'आधा', en: 'Half' },
  Aaj: { hi: 'आज', en: 'Today' },
  'Aaj aaya': { hi: 'आज आया', en: 'Received today' },
  'Aaj ke order': { hi: 'आज के ऑर्डर', en: "Today's orders" },
  'Aaj ki sale': { hi: 'आज की सेल', en: "Today's sales" },
  'Aaj paisa aaya': { hi: 'आज पैसा आया', en: 'Money received today' },
  'Aaj ye dekh lijiye': { hi: 'आज ये देख लीजिए', en: 'Look at this today' },
  'Aakhri baar aaya': { hi: 'आखिरी बार आया', en: 'Last seen' },
  'Aapka account': { hi: 'आपका अकाउंट', en: 'Your account' },
  'Aapka naam': { hi: 'आपका नाम', en: 'Your name' },
  'Aapka saara data aapke apne MongoDB database me hai — hamare paas uski koi copy nahi. Iska matlab: database ka backup on rakhna aapki zimmedari hai.': { hi: 'आपका सारा डेटा आपके अपने MongoDB डेटाबेस में है — हमारे पास उसकी कोई कॉपी नहीं। मतलब: डेटाबेस का बैकअप चालू रखना आपकी ज़िम्मेदारी है।', en: 'All your data lives in your own MongoDB database — we keep no copy. That means keeping database backups on is your responsibility.' },
  'Aapka saara data ek file me — mahine me ek baar le lena achhi aadat hai': { hi: 'आपका सारा डेटा एक फाइल में — महीने में एक बार ले लेना अच्छी आदत है', en: 'All your data in one file — taking it once a month is a good habit' },
  'Aapka saara maal, stock aur rate': { hi: 'आपका सारा माल, स्टॉक और रेट', en: 'All your goods, stock and rates' },
