  Active: { hi: 'चालू', en: 'Active' },
  Add: { hi: 'जोड़ें', en: 'Add' },
  Address: { hi: 'पता', en: 'Address' },
  'Address aur GST': { hi: 'पता और GST', en: 'Address and GST' },
  'Address aur GST bhar lein — invoice pe yahi chhapega. Phir "Invite link" tab se apna link WhatsApp pe bhej dein.': { hi: 'पता और GST भर लें — बिल पर यही छपेगा। फिर "Invite link" टैब से अपना लिंक WhatsApp पर भेज दें।', en: 'Fill in address and GST — this is what prints on the invoice. Then send your link from the "Invite link" tab on WhatsApp.' },
  'Address line 1': { hi: 'पता लाइन 1', en: 'Address line 1' },
  'Address line 2': { hi: 'पता लाइन 2', en: 'Address line 2' },
  advance: { hi: 'एडवांस', en: 'advance' },
  'Agar iska koi order, bill ya payment hai to delete nahi hoga — sirf block ho jayega, taaki purane record kharab na hon.': { hi: 'अगर इसका कोई ऑर्डर, बिल या पेमेंट है तो डिलीट नहीं होगा — सिर्फ ब्लॉक होगा, ताकि पुराने रिकॉर्ड खराब न हों।', en: 'If this party has any order, bill or payment it will not be deleted — only blocked, so old records stay intact.' },
  'Agla page': { hi: 'अगला पेज', en: 'Next page' },
  'Akshar ka size': { hi: 'अक्षर का आकार', en: 'Text size' },
  'Alag alag CSV — CA ko dena ho ya khud dekhna ho': { hi: 'अलग अलग CSV — CA को देना हो या खुद देखना हो', en: 'Separate CSVs — to hand to your CA or to check yourself' },
  Amount: { hi: 'रकम', en: 'Amount' },
  'Amount in words': { hi: 'रकम शब्दों में', en: 'Amount in words' },
  'Apna account': { hi: 'अपना अकाउंट', en: 'My account' },
  'Apna login bana lijiye': { hi: 'अपना लॉगिन बना लीजिए', en: 'Create your login' },
  'Apna password': { hi: 'अपना पासवर्ड', en: 'Your password' },
  'Apne aap approve kar do': { hi: 'अपने आप अप्रूव कर दो', en: 'Approve automatically' },
  'Apne phone number se login karein': { hi: 'अपने फोन नंबर से लॉगिन करें', en: 'Log in with your phone number' },
  'Apni pehchaan ke liye, marzi ho to chhod dein': { hi: 'अपनी पहचान के लिए, मर्ज़ी हो तो छोड़ दें', en: 'For your own reference, optional' },
  'App ka account': { hi: 'ऐप का अकाउंट', en: 'App account' },
  'App ke shabd kis bhasha me dikhein': { hi: 'ऐप के शब्द किस भाषा में दिखें', en: 'Which language the app should use' },
  'Approval baaki': { hi: 'अप्रूवल बाकी', en: 'Approval pending' },
  Approve: { hi: 'अप्रूव करें', en: 'Approve' },
  'Aur item add karein': { hi: 'और आइटम जोड़ें', en: 'Add more items' },
  Baaki: { hi: 'बाकी', en: 'Due' },
  'Badal dein': { hi: 'बदल दें', en: 'Change' },
  'Badalne ke liye list me "Stock" button dabayein': { hi: 'बदलने के लिए लिस्ट में "Stock" बटन दबाएं', en: 'To change it, press the "Stock" button in the list' },
