  Band: { hi: 'बंद', en: 'Off' },
  'Band karein': { hi: 'बंद करें', en: 'Close' },
  'Band karein to poora paisa usi waqt lena hoga': { hi: 'बंद करें तो पूरा पैसा उसी वक्त लेना होगा', en: 'Turn this off and the full amount must be collected at once' },
  'Band karne par koi naya retailer register nahi kar payega': { hi: 'बंद करने पर कोई नया रिटेलर रजिस्टर नहीं कर पाएगा', en: 'When off, no new retailer can register' },
  Barcode: { hi: 'बारकोड', en: 'Barcode' },
  'Bearing sirf 6 hai, baaki agle hafte': { hi: 'बेयरिंग सिर्फ 6 है, बाकी अगले हफ्ते', en: 'Only 6 bearings left, rest next week' },
  'Bearings, Chains, Plugs — jaise apne maal ke hisaab se bana lein.': { hi: 'Bearings, Chains, Plugs — जैसे अपने माल के हिसाब से बना लें।', en: 'Bearings, Chains, Plugs — make them to suit your goods.' },
  'Bhar dein to sirf yahi number jud payega': { hi: 'भर दें तो सिर्फ यही नंबर जुड़ पाएगा', en: 'Fill this and only this number can join' },
  'Bharna zaroori nahi — par bhar denge to search me foran mil jayega': { hi: 'भरना ज़रूरी नहीं — पर भर देंगे तो सर्च में फौरन मिल जाएगा', en: 'Not required — but filling it makes search find it instantly' },
  Bhasha: { hi: 'भाषा', en: 'Language' },
  'Bheji hui link': { hi: 'भेजी हुई लिंक', en: 'Link sent' },
  Bill: { hi: 'बिल', en: 'Bill' },
  'Bill aisa dikhega: INV/26-27/0001': { hi: 'बिल ऐसा दिखेगा: INV/26-27/0001', en: 'The bill will look like: INV/26-27/0001' },
  'Bill aur stock ke chhote settings': { hi: 'बिल और स्टॉक की छोटी सेटिंग', en: 'Small bill and stock settings' },
  'Bill banate hi stock ghatega aur retailer ke khate me udhaar chadhega': { hi: 'बिल बनते ही स्टॉक घटेगा और रिटेलर के खाते में उधार चढ़ेगा', en: 'Making the bill reduces stock and adds credit to the retailer ledger' },
  'Bill banate hi stock ghatta hai aur khata banta hai': { hi: 'बिल बनते ही स्टॉक घटता है और खाता बनता है', en: 'Making a bill reduces stock and creates the ledger entry' },
  'Bill banayein': { hi: 'बिल बनाएं', en: 'Create bill' },
  'Bill banega ya paisa aayega tab yahan dikhega': { hi: 'बिल बनेगा या पैसा आएगा तब यहां दिखेगा', en: 'Shows up here when a bill is made or money comes in' },
  'Bill banega, paisa aayega ya koi setting badlegi — sab yahan likha jayega.': { hi: 'बिल बनेगा, पैसा आएगा या कोई सेटिंग बदलेगी — सब यहां लिखा जाएगा।', en: 'Bills, payments and setting changes — everything gets recorded here.' },
  'Bill chhapte waqt hamesha safed kagaz hi chhapega — chahe raat wala roop chalu ho.': { hi: 'बिल छापते वक्त हमेशा सफेद कागज ही छपेगा — चाहे रात वाला रूप चालू हो।', en: 'Printing always uses the light theme — even when dark mode is on.' },
  'Bill dekhein': { hi: 'बिल देखें', en: 'View bill' },
  'Bill delete nahi hoga — number record me rahega, par stock wapas aa jayega aur khata ulta ho jayega.': { hi: 'बिल डिलीट नहीं होगा — नंबर रिकॉर्ड में रहेगा, पर स्टॉक वापस आ जाएगा और खाता उल्टा हो जाएगा।', en: 'The bill is not deleted — the number stays on record, but stock returns and the ledger is reversed.' },
  'Bill isse bada nahi': { hi: 'बिल इससे बड़ा नहीं', en: 'Bill cannot exceed this' },
  'Bill number ya retailer...': { hi: 'बिल नंबर या रिटेलर...', en: 'Bill number or retailer...' },
  'Bill pe extra discount': { hi: 'बिल पर अतिरिक्त छूट', en: 'Extra discount on bill' },
  'Bill pe IGST lagega ya CGST+SGST — isse tay hoga': { hi: 'बिल पर IGST लगेगा या CGST+SGST — इससे तय होगा', en: 'Decides whether IGST or CGST+SGST applies on the bill' },
  'Bill to': { hi: 'बिल किसके नाम', en: 'Bill to' },
  Bills: { hi: 'बिल', en: 'Bills' },
  'Bina bill': { hi: 'बिना बिल', en: 'Without bill' },
  'Bina category': { hi: 'बिना श्रेणी', en: 'No category' },
  'Bina GST ke bhi poori app chalegi — items, orders, khata, payments sab kuch. Bas bill pe tax nahi lagega.': { hi: 'बिना GST के भी पूरी ऐप चलेगी — आइटम, ऑर्डर, खाता, पेमेंट सब कुछ। बस बिल पर टैक्स नहीं लगेगा।', en: 'The whole app works without GST too — items, orders, ledger, payments. Only tax will not apply on bills.' },
  Block: { hi: 'ब्लॉक करें', en: 'Block' },
  Cancel: { hi: 'रहने दें', en: 'Cancel' },
  'Cash, UPI, bank — paisa aane-jaane ka poora record': { hi: 'कैश, UPI, बैंक — पैसे के आने-जाने का पूरा रिकॉर्ड', en: 'Cash, UPI, bank — the full record of money in and out' },
  Categories: { hi: 'श्रेणियां', en: 'Categories' },
