  Chhupayein: { hi: 'छुपाएं', en: 'Hide' },
  'Chune hue items ka khaas rate hat jayega — un par wapas wholesale price lagega.': { hi: 'चुने हुए आइटम का खास रेट हट जाएगा — उन पर वापस होलसेल प्राइस लगेगा।', en: 'The special rate on the selected items will be removed — wholesale price applies again.' },
