  Diya: { hi: 'दिया', en: 'Paid' },
  'Do minute me apni dukaan set kar lein': { hi: 'दो मिनट में अपनी दुकान सेट कर लें', en: 'Set up your shop in two minutes' },
  'Dukaan ka naam': { hi: 'दुकान का नाम', en: 'Shop name' },
  'Dukaan ke log': { hi: 'दुकान के लोग', en: 'Shop staff' },
  'Dukaan ke malik ne aapko is hisse ki ijazat nahi di hai. Zarurat ho to unse kahiye.': { hi: 'दुकान के मालिक ने आपको इस हिस्से की इजाज़त नहीं दी है। ज़रूरत हो तो उनसे कहिए।', en: 'The shop owner has not given you access to this section. Ask them if you need it.' },
  'Dukaan ke malik se nayi link mangwa lijiye.': { hi: 'दुकान के मालिक से नई लिंक मंगवा लीजिए।', en: 'Ask the shop owner for a fresh link.' },
  'Dukaan ki detail': { hi: 'दुकान की जानकारी', en: 'Shop details' },
