  'Kam bache': { hi: 'कम बचे', en: 'Running low' },
  'Kam se kam 6 character': { hi: 'कम से कम 6 अक्षर', en: 'At least 6 characters' },
  'Kam se kam 6 character. Ye sirf aapko pata rahega — malik ko bhi nahi.': { hi: 'कम से कम 6 अक्षर। ये सिर्फ आपको पता रहेगा — मालिक को भी नहीं।', en: 'At least 6 characters. Only you will know it — not even the owner.' },
  'Kam se kam order': { hi: 'कम से कम ऑर्डर', en: 'Minimum order' },
