  'Karan:': { hi: 'कारण:', en: 'Reason:' },
  'Kaunsa maal wapas': { hi: 'कौन सा माल वापस', en: 'Which goods are being returned' },
  'Kaunse items pe': { hi: 'किन आइटम पर', en: 'On which items' },
