  'Khata wapas pehle jaisa ho jayega aur bill dobara udhaar dikhne lagega. Ye wapas nahi hota.': { hi: 'खाता वापस पहले जैसा हो जाएगा और बिल दोबारा उधार दिखने लगेगा। ये वापस नहीं होता।', en: 'The ledger goes back to how it was and the bill shows as unpaid again. This cannot be undone.' },
  Khatam: { hi: 'खत्म', en: 'Out of stock' },
  Kholein: { hi: 'खोलें', en: 'Open' },
  'Kis liye (sirf aapki yaad ke liye)': { hi: 'किस लिए (सिर्फ आपकी याद के लिए)', en: 'What for (just for your own reference)' },
