  'kisse kitna lena hai — dekhein': { hi: 'किससे कितना लेना है — देखें', en: 'see who owes you' },
  'Kisse kitna lena hai, kisko kitna dena hai — sab ek jagah': { hi: 'किससे कितना लेना है, किसको कितना देना है — सब एक जगह', en: 'Who owes you and whom you owe — all in one place' },
  Kitna: { hi: 'कितना', en: 'How much' },
