  'Link banayein': { hi: 'लिंक बनाएं', en: 'Create link' },
  'Link bhej dijiye — aane wala khud apna naam aur password banayega. Aapko uska password kabhi pata nahi chalega.': { hi: 'लिंक भेज दीजिए — आने वाला खुद अपना नाम और पासवर्ड बनाएगा। आपको उसका पासवर्ड कभी पता नहीं चलेगा।', en: 'Just send the link — they will set their own name and password. You will never see their password.' },
  'Link chalu rakhein': { hi: 'लिंक चालू रखें', en: 'Keep the link active' },
  'Link kaam nahi kar raha': { hi: 'लिंक काम नहीं कर रहा', en: 'This link is not working' },
  'Link kaam nahi kar rahi': { hi: 'लिंक काम नहीं कर रही', en: 'This link is not working' },
