  'Link tayyar hai': { hi: 'लिंक तैयार है', en: 'Link is ready' },
  'List, approve/block, party-wise rate aur khata — sab Retailers page pe': { hi: 'लिस्ट, अप्रूव/ब्लॉक, पार्टी-वार रेट और खाता — सब रिटेलर पेज पर', en: 'List, approve/block, party-wise rates and ledger — all on the Retailers page' },
  'Login chalu hai': { hi: 'लॉगिन चालू है', en: 'Login is active' },
