  Maal: { hi: 'माल', en: 'Goods' },
  'Maal wapas aaya': { hi: 'माल वापस आया', en: 'Goods returned to us' },
  'Maal wapas aaya ya bheja — stock aur khata dono apne aap theek ho jate hain': { hi: 'माल वापस आया या भेजा — स्टॉक और खाता दोनों अपने आप ठीक हो जाते हैं', en: 'Goods returned in or sent back — both stock and ledger fix themselves' },
  'Maal wapas bheja': { hi: 'माल वापस भेजा', en: 'Goods sent back' },
  'Maal wapas nahi hoga': { hi: 'माल वापस नहीं होगा', en: 'Goods are not returnable' },
  'Maal wapas nahi hoga. Payment 30 din me.': { hi: 'माल वापस नहीं होगा। पेमेंट 30 दिन में।', en: 'Goods are not returnable. Payment within 30 days.' },
  'Mahine ka hisaab, CA ko dene layak': { hi: 'महीने का हिसाब, CA को देने लायक', en: 'Monthly summary, ready to hand to your CA' },
  Mangi: { hi: 'मांगी', en: 'Ordered' },
  Menu: { hi: 'मेन्यू', en: 'Menu' },
  'Menu band karein': { hi: 'मेन्यू बंद करें', en: 'Close menu' },
  'Meri dukaan GST registered hai': { hi: 'मेरी दुकान GST रजिस्टर्ड है', en: 'My shop is GST registered' },
  'Mil gaya': { hi: 'मिल गया', en: 'Received' },
  'Model / Serial number': { hi: 'मॉडल / सीरियल नंबर', en: 'Model / Serial number' },
  'MongoDB Atlas use kar rahe hain to wahan settings me automatic backup on kar dijiye. Uske alawa mahine me ek baar upar wali JSON file bhi le liya karein — dono alag alag cheezein hain.': { hi: 'MongoDB Atlas इस्तेमाल कर रहे हैं तो वहां सेटिंग में अपने आप बैकअप चालू कर दीजिए। उसके अलावा महीने में एक बार ऊपर वाली JSON फाइल भी ले लिया करें — दोनों अलग अलग चीज़ें हैं।', en: 'If you use MongoDB Atlas, turn on automatic backup in its settings. Also take the JSON file above once a month — the two are different things.' },
  Naam: { hi: 'नाम', en: 'Name' },
  'Naam badlein': { hi: 'नाम बदलें', en: 'Rename' },
  'Naam ya phone se dhoondhein': { hi: 'नाम या फोन से ढूंढें', en: 'Search by name or phone' },
