  'Sirf aapka apna — kisi aur ka yahan se nahi badalta': { hi: 'सिर्फ आपका अपना — किसी और का यहां से नहीं बदलता', en: 'Only yours — nobody else can be changed from here' },
  'Sirf akshar nahi — button aur khaane bhi utne hi bade honge, taaki ungli se dabane me aasani rahe.': { hi: 'सिर्फ अक्षर नहीं — बटन और खाने भी उतने ही बड़े होंगे, ताकि उंगली से दबाने में आसानी रहे।', en: 'Not just the text — buttons and fields grow too, so they are easier to tap.' },
  'Sirf apna kaam': { hi: 'सिर्फ अपना काम', en: 'Own work only' },
  'Sirf is number ke liye (marzi se)': { hi: 'सिर्फ इस नंबर के लिए (मर्ज़ी से)', en: 'For this number only (optional)' },
  'Sirf malik bana sakta hai': { hi: 'सिर्फ मालिक बना सकता है', en: 'Only the owner can create this' },
  'Sirf nayi': { hi: 'सिर्फ नई', en: 'Unread only' },
  'Sirf wahi retailer dikhenge jo inke naam hain ya jo inhone khud jode. Unke order, bill aur khata bhi apne aap isi hadd me aa jayenge.': { hi: 'सिर्फ वही रिटेलर दिखेंगे जो इनके नाम हैं या जो इन्होंने खुद जोड़े। उनके ऑर्डर, बिल और खाता भी अपने आप इसी हद में आ जाएंगे।', en: 'They will only see retailers assigned to them or added by them. Those orders, bills and ledgers are limited the same way automatically.' },
  State: { hi: 'राज्य', en: 'State' },
  'State chunein': { hi: 'राज्य चुनें', en: 'Choose state' },
  Stock: { hi: 'स्टॉक', en: 'Stock' },
  'Stock badlein': { hi: 'स्टॉक बदलें', en: 'Adjust stock' },
  'Stock ki keemat': { hi: 'स्टॉक की कीमत', en: 'Stock value' },
  'Stock pe asar': { hi: 'स्टॉक पर असर', en: 'Effect on stock' },
  'Stock utna hi wapas ghat jayega aur supplier ka khata bhi ulta ho jayega. Agar wo maal bik chuka hai to delete nahi hoga.': { hi: 'स्टॉक उतना ही वापस घट जाएगा और सप्लायर का खाता भी उल्टा हो जाएगा। अगर वो माल बिक चुका है तो डिलीट नहीं होगा।', en: 'Stock is reduced back by the same amount and the supplier ledger is reversed. If those goods are already sold it will not delete.' },
