  'Ye daal denge to retailer apne phone se seedha aapko paisa bhej payega': { hi: 'ये डाल देंगे तो रिटेलर अपने फोन से सीधे आपको पैसा भेज पाएगा', en: 'Fill this and retailers can pay you straight from their phone' },
  'Ye data kahan rehta hai': { hi: 'ये डेटा कहां रहता है', en: 'Where this data lives' },
  'Ye file aapke computer me download hogi — kahin upload nahi hoti. Password kabhi is file me nahi jata. File ko Google Drive ya pendrive me rakh dijiye.': { hi: 'ये फाइल आपके कंप्यूटर में डाउनलोड होगी — कहीं अपलोड नहीं होती। पासवर्ड कभी इस फाइल में नहीं जाता। फाइल को Google Drive या पेनड्राइव में रख दीजिए।', en: 'This file downloads to your computer — it is not uploaded anywhere. Passwords never go into it. Keep the file on Google Drive or a pen drive.' },
  'Ye khatam hone wale hain': { hi: 'ये खत्म होने वाले हैं', en: 'These are about to run out' },
  'Ye link ab dobara nahi dikhegi.': { hi: 'ये लिंक अब दोबारा नहीं दिखेगी।', en: 'This link will not be shown again.' },
  'Ye link sirf dukaan ke malik ke paas rehta hai. Kisi naye retailer ko jodna ho to unse link mangwa lijiye.': { hi: 'ये लिंक सिर्फ दुकान के मालिक के पास रहता है। किसी नए रिटेलर को जोड़ना हो तो उनसे लिंक मंगवा लीजिए।', en: 'Only the shop owner holds this link. To add a new retailer, ask them for it.' },
  'Ye notification hatayein': { hi: 'ये सूचना हटाएं', en: 'Remove this notification' },
  'Ye page aapke liye nahi khula': { hi: 'ये पेज आपके लिए नहीं खुला', en: 'This page is not open to you' },
  'Ye sirf andaza hai — asli return CA hi bharega. Yahan se CSV nikaal kar de dijiye.': { hi: 'ये सिर्फ अंदाज़ा है — असली रिटर्न CA ही भरेगा। यहां से CSV निकाल कर दे दीजिए।', en: 'This is only an estimate — your CA files the actual return. Export the CSV here and hand it over.' },
