  'Naye leads': { hi: 'नए लीड्स', en: 'New leads' },
  'Follow-up chahiye': { hi: 'फॉलो-अप चाहिए', en: 'Needs follow-up' },
  'Dead': { hi: 'डेड', en: 'Dead' },
  'Chalu retailer': { hi: 'चालू रिटेलर', en: 'Active retailers' },
  'Cart mein maal pada hai, order abhi nahi diya': { hi: 'कार्ट में माल पड़ा है, ऑर्डर अभी नहीं दिया', en: 'Items sitting in cart, order not placed yet' },
  'Abhi kisi ke cart mein kuch pada nahi hai': { hi: 'अभी किसी के कार्ट में कुछ पड़ा नहीं है', en: 'No one has anything in their cart right now' },
