  'Purana graahak': { hi: 'पुराना ग्राहक', en: 'Returning customer' },
  'Pehle order dete the, ab 15+ din se chup hain': { hi: 'पहले ऑर्डर देते थे, अब 15+ दिन से चुप हैं', en: 'Used to order, gone quiet for 15+ days' },
  'Koi follow-up baaki nahi hai': { hi: 'कोई फॉलो-अप बाकी नहीं है', en: 'No follow-ups pending' },
