  'Ab tak {a0} ka business': { hi: 'अब तक {a0} का बिज़नेस', en: '{a0} in business so far' },
  '45+ din se gayab, ya kabhi order kiya hi nahi': { hi: '45+ दिन से गायब, या कभी ऑर्डर किया ही नहीं', en: 'Gone for 45+ days, or never ordered at all' },
  'Koi retailer gayab nahi hai — sab sahi hai': { hi: 'कोई रिटेलर गायब नहीं है — सब सही है', en: 'No retailer has gone dark — all good' },
  'Kabhi order nahi diya': { hi: 'कभी ऑर्डर नहीं दिया', en: 'Never placed an order' },
  '{n} din se gayab': { hi: '{n} दिन से गायब', en: 'Gone for {n} days' },
  'Pehle {a0} ka business tha': { hi: 'पहले {a0} का बिज़नेस था', en: 'Used to be {a0} in business' },
  'In sabse pehle mila kar kareeb {a0} ka business tha — yahi ab daanv pe hai': { hi: 'इन सबसे पहले मिलाकर करीब {a0} का बिज़नेस था — यही अब दांव पे है', en: 'These accounts used to bring in about {a0} combined — that is what is now at risk' },
  'Load nahi hua': { hi: 'लोड नहीं हुआ', en: 'Could not load' },
