  'Bhej diya': { hi: 'भेज दिया', en: 'Sent' },
  'Naam ya code se': { hi: 'नाम या कोड से', en: 'By name or code' },
  'Kram': { hi: 'क्रम', en: 'Sort' },
  '{q} available': { hi: '{q} उपलब्ध', en: '{q} available' },
  'Stock khatam': { hi: 'स्टॉक खत्म', en: 'Out of stock' },
  '{naam} ka cart khali kar diya': { hi: '{naam} का कार्ट खाली कर दिया', en: 'Cleared the cart for {naam}' },
  'Abhi koi dukaan order lene layak nahi hai': { hi: 'अभी कोई दुकान ऑर्डर लेने लायक नहीं है', en: 'No shop is ready to take an order yet' },
  'Order chala gaya': { hi: 'ऑर्डर चला गया', en: 'Order sent' },
  'Inka order nahi ja saka — inka maal cart me hi hai': { hi: 'इनका ऑर्डर नहीं जा सका — इनका माल कार्ट में ही है', en: 'These orders could not be sent — their goods are still in the cart' },
  'Aur maal lein': { hi: 'और माल लें', en: 'Add more goods' },
  'Cart dekhein': { hi: 'कार्ट देखें', en: 'View cart' },
  'Dukaan chun kar item cart me daalein — kai dukaanon ka maal ek saath bhi bhej sakte hain.': { hi: 'दुकान चुन कर आइटम कार्ट में डालें — कई दुकानों का माल एक साथ भी भेज सकते हैं।', en: 'Pick a shop and add items — you can order from several shops at once.' },
  'Dukaan kholein': { hi: 'दुकान खोलें', en: 'Open a shop' },
  'Kul jod': { hi: 'कुल जोड़', en: 'Grand total' },
  '{n} dukaan ne abhi approve nahi kiya — unka order nahi jayega, maal cart me hi rahega.': { hi: '{n} दुकान ने अभी अप्रूव नहीं किया — उनका ऑर्डर नहीं जाएगा, माल कार्ट में ही रहेगा।', en: '{n} shop(s) have not approved you yet — their order will not go, the goods stay in the cart.' },
  'Har dukaan ko uska apna order jayega — bill abhi nahi banega.': { hi: 'हर दुकान को उसका अपना ऑर्डर जाएगा — बिल अभी नहीं बनेगा।', en: 'Each shop gets its own order — no bill is made yet.' },
  'Is dukaan ka cart khali karein?': { hi: 'इस दुकान का कार्ट खाली करें?', en: 'Clear this shop\'s cart?' },
  'Sirf {naam} ka maal hatega — baaki dukaanon ka waise ka waisa rahega.': { hi: 'सिर्फ {naam} का माल हटेगा — बाकी दुकानों का वैसे का वैसा रहेगा।', en: 'Only {naam}\'s items are removed — the other shops stay as they are.' },
  '{naam} kholein': { hi: '{naam} खोलें', en: 'Open {naam}' },
  '{naam} ka cart khali karein': { hi: '{naam} का कार्ट खाली करें', en: 'Clear {naam}\'s cart' },
  'Is dukaan ka jod': { hi: 'इस दुकान का जोड़', en: 'This shop\'s total' },
  '{naam} ke liye note': { hi: '{naam} के लिए नोट', en: 'Note for {naam}' },
  'Note likhein': { hi: 'नोट लिखें', en: 'Add a note' },
  /* ── Part 17 step 2: dukaan badalne ki patti ── */
  'Nayi dukaan jodein': { hi: 'नई दुकान जोड़ें', en: 'Add a new shop' },
  'Aur': { hi: 'और', en: 'More' },
  /* ── Part 17 step 3: kharida hua maal apni dukaan me ── */
  'Maal stock me': { hi: 'माल स्टॉक में', en: 'Add to stock' },
  'Doosri dukaan se aaya maal apne stock me chadhayein': { hi: 'दूसरी दुकान से आया माल अपने स्टॉक में चढ़ाएं', en: 'Put goods received from another shop into your stock' },
  'Maal stock me daalein': { hi: 'माल स्टॉक में डालें', en: 'Add goods to stock' },
  'Doosri dukaan se jo maal aaya, use apne stock me chadhayein': { hi: 'दूसरी दुकान से जो माल आया, उसे अपने स्टॉक में चढ़ाएं', en: 'Put the goods you received into your own stock' },
  'Koi kaam baaki nahi': { hi: 'कोई काम बाकी नहीं', en: 'Nothing pending' },
  'Yahan kuch nahi hai': { hi: 'यहां कुछ नहीं है', en: 'Nothing here' },
  'Jab doosri dukaan aapko bill degi, uska maal yahan apne aap aa jayega.': { hi: 'जब दूसरी दुकान आपको बिल देगी, उसका माल यहां अपने आप आ जाएगा।', en: 'When another shop bills you, its goods appear here automatically.' },
  'Doosri chhalni chun kar dekhein.': { hi: 'दूसरी छलनी चुन कर देखें।', en: 'Try another filter.' },
  '{a} / {b} ho gaya': { hi: '{a} / {b} हो गया', en: '{a} / {b} done' },
  'Jab tak ye kaam baaki hai, ye maal aapke stock me nahi hai — bechne par stock minus me chala jayega.': { hi: 'जब तक ये काम बाकी है, ये माल आपके स्टॉक में नहीं है — बेचने पर स्टॉक माइनस में चला जाएगा।', en: 'Until this is done the goods are not in your stock — selling them will push stock negative.' },
  'Doosri dukaan se maal mangwane ke liye Settings me Buyer mode chunein.': { hi: 'दूसरी दुकान से माल मंगवाने के लिए Settings में Buyer mode चुनें।', en: 'To order from another shop, switch to Buyer mode in Settings.' },
  'Maal stock me aa gaya': { hi: 'माल स्टॉक में आ गया', en: 'Goods added to stock' },
  '{n} item aapke stock me chadh gaye': { hi: '{n} आइटम आपके स्टॉक में चढ़ गए', en: '{n} items went into your stock' },
  'Bill {no} · {date}': { hi: 'बिल {no} · {date}', en: 'Bill {no} · {date}' },
  'Purchase dekhein': { hi: 'खरीद देखें', en: 'View purchase' },
  'Baaki kaam dekhein': { hi: 'बाकी काम देखें', en: 'See pending work' },
  'Ye bill cancel ho gaya': { hi: 'ये बिल कैंसिल हो गया', en: 'This bill was cancelled' },
  'Bechne wale ne bill cancel kar diya': { hi: 'बेचने वाले ने बिल कैंसिल कर दिया', en: 'The seller cancelled the bill' },
  'Is maal ko stock me daalne ki zarurat nahi.': { hi: 'इस माल को स्टॉक में डालने की ज़रूरत नहीं।', en: 'No need to add these goods to stock.' },
  '{naam} · bill {no}': { hi: '{naam} · बिल {no}', en: '{naam} · bill {no}' },
  '{a} / {b} item ho gaye': { hi: '{a} / {b} आइटम हो गए', en: '{a} / {b} items done' },
  'Bechne ka rate daalein': { hi: 'बेचने का रेट डालें', en: 'Enter the selling price' },
  'Bill me ye likha hai': { hi: 'बिल में ये लिखा है', en: 'The bill says' },
  '{q} × {r}': { hi: '{q} × {r}', en: '{q} × {r}' },
  'GST {n}%': { hi: 'GST {n}%', en: 'GST {n}%' },
