  '(GST bhi isme jud gaya — aapki dukaan GST me registered nahi hai)': { hi: '(GST भी इसमें जुड़ गया — आपकी दुकान GST में रजिस्टर्ड नहीं है)', en: '(GST is included — your shop is not GST registered)' },
  'Ye aapka kaunsa item hai?': { hi: 'ये आपका कौन सा आइटम है?', en: 'Which of your items is this?' },
  'Mil jaye to usi ka stock badhega, warna naya ban jayega': { hi: 'मिल जाए तो उसी का स्टॉक बढ़ेगा, वरना नया बन जाएगा', en: 'If matched its stock grows, otherwise a new item is created' },
  'Pakka yahi': { hi: 'पक्का यही', en: 'Exact match' },
  'Shayad': { hi: 'शायद', en: 'Maybe' },
  'Abhi {q}': { hi: 'अभी {q}', en: 'Now {q}' },
  'bech rahe {a}': { hi: 'बेच रहे {a}', en: 'selling at {a}' },
  'Naya item banayein': { hi: 'नया आइटम बनाएं', en: 'Create a new item' },
  'Apna code': { hi: 'अपना कोड', en: 'Your code' },
  'Marzi se — apne godown ka code': { hi: 'मर्ज़ी से — अपने गोदाम का कोड', en: 'Optional — your own godown code' },
  'Bechne ka rate': { hi: 'बेचने का रेट', en: 'Selling price' },
  'Ye rate item pe lag jayega — baad me Items page se badal sakte hain': { hi: 'ये रेट आइटम पर लग जाएगा — बाद में Items पेज से बदल सकते हैं', en: 'This price is set on the item — you can change it later from Items' },
  'Ek {u} kitne ka bechenge': { hi: 'एक {u} कितने का बेचेंगे', en: 'Selling price per {u}' },
  'Lagat pe jodein': { hi: 'लागत पर जोड़ें', en: 'Add on cost' },
