  'Retailer jab aapki dukaan kholega, sabse upar yahi dikhega': { hi: 'रिटेलर जब आपकी दुकान खोलेगा, सबसे ऊपर यही दिखेगा', en: 'This shows at the top when a retailer opens your shop' },
