  'Aap is dukaan se jude nahi hain. Pehle number search karke jodein.': { hi: 'आप इस दुकान से जुड़े नहीं हैं। पहले नंबर खोजकर जोड़ें।', en: 'You are not connected to this shop. Search its number and connect first.' },
