  'Bahut baar bhej chuke hain. Ek ghante baad koshish karein.': { hi: 'बहुत बार भेज चुके हैं। एक घंटे बाद कोशिश करें।', en: 'Too many attempts. Please try again in an hour.' },
  'Bahut baar galat daala — naya OTP mangwaiye': { hi: 'बहुत बार गलत डाला — नया OTP मंगवाइए', en: 'Too many wrong attempts — request a new OTP' },
  'Band ho chuke order me badlav nahi ho sakta': { hi: 'बंद हो चुके ऑर्डर में बदलाव नहीं हो सकता', en: 'A closed order cannot be changed' },
  'Bata diya gaya — wholesaler confirm karega tab khate me lagega': { hi: 'बता दिया गया — होलसेलर कन्फर्म करेगा तब खाते में लगेगा', en: 'Sent — it will reflect in your ledger once the wholesaler confirms' },
  'Bechne ka rate daalna zaroori hai': { hi: 'बेचने का रेट डालना ज़रूरी है', en: 'Selling price is required' },
  'Bill nahi mila': { hi: 'बिल नहीं मिला', en: 'Bill not found' },
