  'CSV khali hai': { hi: 'CSV खाली है', en: 'The CSV is empty' },
  'CSV me "name" column hona zaroori hai. Sample file download karke dekh lein.': { hi: 'CSV में "name" कॉलम होना ज़रूरी है। सैंपल फ़ाइल डाउनलोड करके देख लें।', en: 'The CSV needs a "name" column. Download the sample file to check.' },
  'CSV me koi row nahi mili': { hi: 'CSV में कोई लाइन नहीं मिली', en: 'No rows found in the CSV' },
  'Cancel ho chuke order pe payment nahi lag sakti': { hi: 'कैंसिल हो चुके ऑर्डर पर पेमेंट नहीं लग सकती', en: 'A payment can\'t be recorded on a cancelled order' },
