  'Cart ke saare item ab available nahi hain — cart dobara dekh lein': { hi: 'कार्ट के सारे आइटम अब उपलब्ध नहीं हैं — कार्ट दोबारा देख लें', en: 'None of the cart items are available now — please check your cart' },
  'Cart se hata diya': { hi: 'कार्ट से हटा दिया', en: 'Removed from cart' },
  'Cart update ho gaya': { hi: 'कार्ट अपडेट हो गया', en: 'Cart updated' },
  'Category ban gayi': { hi: 'कैटेगरी बन गई', en: 'Category created' },
