  'Category save ho gayi': { hi: 'कैटेगरी सेव हो गई', en: 'Category saved' },
  'De diya — record me chadh gaya': { hi: 'दे दिया — रिकॉर्ड में चढ़ गया', en: 'Delivered — recorded' },
  'Delivered order cancel nahi ho sakta': { hi: 'डिलीवर हो चुका ऑर्डर कैंसिल नहीं हो सकता', en: 'A delivered order can\'t be cancelled' },
  'Discount rate se zyada nahi ho sakta': { hi: 'डिस्काउंट रेट से ज़्यादा नहीं हो सकता', en: 'Discount can\'t be more than the rate' },
  'Dobara chun lijiye': { hi: 'दोबारा चुन लीजिए', en: 'Please choose again' },
  'Dobara login karein': { hi: 'दोबारा लॉगिन करें', en: 'Please log in again' },
  'Dukaan ka naam daalein': { hi: 'दुकान का नाम डालें', en: 'Enter the shop name' },
  'Dukaan ka payment ruka hua hai. Malik se sampark karein — unke payment karte hi aap dobara login kar sakenge.': { hi: 'दुकान का पेमेंट रुका हुआ है। मालिक से संपर्क करें — उनके पेमेंट करते ही आप दोबारा लॉगिन कर सकेंगे।', en: 'The shop\'s subscription payment is pending. Contact the owner — you can log in again once they pay.' },
  'Dukaan ki pehchan galat hai': { hi: 'दुकान की पहचान गलत है', en: 'Invalid shop' },
  'Dukaan nahi mili': { hi: 'दुकान नहीं मिली', en: 'Shop not found' },
  'Dukaan save ho gayi': { hi: 'दुकान सेव हो गई', en: 'Shop saved' },
  'Ek baar me 2000 se zyada item nahi ho sakte': { hi: 'एक बार में 2000 से ज़्यादा आइटम नहीं हो सकते', en: 'No more than 2000 items at a time' },
  'Ek baar me 500 se zyada nahi': { hi: 'एक बार में 500 से ज़्यादा नहीं', en: 'No more than 500 at a time' },
  'Ek bhi item stock me daalne ke liye nahi chuna': { hi: 'स्टॉक में डालने के लिए एक भी आइटम नहीं चुना', en: 'No item was chosen to add to stock' },
  'Ek bhi sahi row nahi mili — errors theek karke dobara try karein': { hi: 'एक भी सही लाइन नहीं मिली — गलतियाँ ठीक करके दोबारा कोशिश करें', en: 'No valid rows found — fix the errors and try again' },
  'Email galat hai': { hi: 'ईमेल गलत है', en: 'Invalid email' },
