  'Indian mobile number 6-9 se shuru hota hai': { hi: 'भारतीय मोबाइल नंबर 6-9 से शुरू होता है', en: 'Indian mobile numbers start with 6-9' },
  'Inka hisaab barabar hai, yaad dilane ki zarurat nahi': { hi: 'इनका हिसाब बराबर है, याद दिलाने की ज़रूरत नहीं', en: 'They are settled — no reminder needed' },
  'Invite link galat hai ya expire ho gaya': { hi: 'इनवाइट लिंक गलत है या एक्सपायर हो गया', en: 'The invite link is invalid or has expired' },
  'Is dukaan ka koi plan/trial nahi — pehle plan lagaiye': { hi: 'इस दुकान का कोई प्लान/ट्रायल नहीं — पहले प्लान लगाइए', en: 'This shop has no plan or trial — choose a plan first' },
  'Is dukaan ne aapka access band kar rakha hai': { hi: 'इस दुकान ने आपका एक्सेस बंद कर रखा है', en: 'This shop has blocked your access' },
  'Is filter me koi item nahi mila': { hi: 'इस फ़िल्टर में कोई आइटम नहीं मिला', en: 'No items match this filter' },
  'Is number pe koi dukaan nahi mili. Number dobara dekh lein.': { hi: 'इस नंबर पर कोई दुकान नहीं मिली। नंबर दोबारा देख लें।', en: 'No shop found on this number. Please check the number.' },
  'Is number se ek account pehle se hai. Doosra number use karein ya login karein.': { hi: 'इस नंबर से एक अकाउंट पहले से है। दूसरा नंबर इस्तेमाल करें या लॉगिन करें।', en: 'An account already exists with this number. Use another number or log in.' },
  'Is order ka bill ban chuka hai — pehle bill cancel karein': { hi: 'इस ऑर्डर का बिल बन चुका है — पहले बिल कैंसिल करें', en: 'This order is already billed — cancel the bill first' },
