  '{a} ka maal aap stock me daal chuke hain — apni purchase dekh lijiye': { hi: '{a} का माल आप स्टॉक में डाल चुके हैं — अपनी खरीद देख लीजिए', en: 'You already added the goods from {a} to stock — please check your purchase' },
  '{a} — wo maal ab stock me daalne ki zarurat nahi': { hi: '{a} — वो माल अब स्टॉक में डालने की ज़रूरत नहीं', en: '{a} — those goods no longer need to be added to stock' },
  '{a} item · {b} — apne stock me daal lijiye': { hi: '{a} आइटम · {b} — अपने स्टॉक में डाल लीजिए', en: '{a} items · {b} — add them to your stock' },
