  '{a} — ₹{b} (maal wapas bheja)': { hi: '{a} — ₹{b} (माल वापस भेजा)', en: '{a} — ₹{b} (goods sent back)' },
  '{a} ka maal badla — ab {b} item, ₹{c}': { hi: '{a} का माल बदला — अब {b} आइटम, ₹{c}', en: 'Changed items in {a} — now {b} items, ₹{c}' },
  '{a} confirm kiya — ₹{b} khate me laga': { hi: '{a} कन्फर्म किया — ₹{b} खाते में लगा', en: 'Confirmed {a} — ₹{b} applied to the ledger' },
  '{a} — ₹{b} diya ({c})': { hi: '{a} — ₹{b} दिया ({c})', en: '{a} — ₹{b} paid ({c})' },
  '{a} — ₹{b} liya ({c})': { hi: '{a} — ₹{b} लिया ({c})', en: '{a} — ₹{b} received ({c})' },
