  'Dukaan ka malik — sab kuch kar sakta hai': { hi: 'दुकान का मालिक — सब कुछ कर सकता है', en: 'Shop owner — can do everything' },
  'Malik jitna hi kaam. Malik ko chhed nahi sakta': { hi: 'मालिक जितना ही काम। मालिक को छेड़ नहीं सकता', en: 'Same as the owner, but can\'t change the owner' },
  'Poori dukaan chalata hai — staff aur settings chhod kar': { hi: 'पूरी दुकान चलाता है — स्टाफ और सेटिंग्स छोड़कर', en: 'Runs the whole shop except staff and settings' },
  'Order aur bill banata hai. Sirf apne retailer dikhte hain': { hi: 'ऑर्डर और बिल बनाता है। सिर्फ अपने रिटेलर दिखते हैं', en: 'Makes orders and bills. Sees only their own retailers' },
  'Paisa aur hisaab. Stock se lena-dena nahi': { hi: 'पैसा और हिसाब। स्टॉक से लेना-देना नहीं', en: 'Money and accounts. No stock access' },
  'Sirf dekh sakta hai — ek bhi cheez badal nahi sakta': { hi: 'सिर्फ देख सकता है — एक भी चीज़ बदल नहीं सकता', en: 'View only — can\'t change anything' },
  'Maal andar-bahar. Paise ka kuch nahi dikhta': { hi: 'माल अंदर-बाहर। पैसे का कुछ नहीं दिखता', en: 'Stock in and out. Sees no money' },
