  'Employee, attendance, chhutti aur salary sambhalta hai': { hi: 'कर्मचारी, हाज़िरी, छुट्टी और सैलरी संभालता है', en: 'Handles employees, attendance, leave and salary' },
  'Sirf apna kaam, attendance, chhutti aur salary dekhta hai': { hi: 'सिर्फ अपना काम, हाज़िरी, छुट्टी और सैलरी देखता है', en: 'Sees only their own tasks, attendance, leave and salary' },
